diff --git a/main.c b/main.c
index 14bdd72..fc572bc 100644
--- a/main.c
+++ b/main.c
@@ -6,0 +7,11 @@
+#define MAX_REQUESTED 4096U
+
+static int add_capacity(size_t requested, size_t *allocation_size)
+{
+    if (requested > SIZE_MAX - 16 || requested > MAX_REQUESTED) {
+        return 0;
+    }
+    *allocation_size = requested + 16;
+    return 1;
+}
+
@@ -25 +35,0 @@ int main(void)
-    size_t requested = (size_t)parsed;
@@ -27,2 +37,4 @@ int main(void)
-    /* Vulnerability: the addition can wrap before allocation. */
-    size_t allocation_size = requested + 16;
+    size_t allocation_size = 0;
+    if (!add_capacity((size_t)parsed, &allocation_size)) {
+        return 2;
+    }
@@ -34,0 +47,4 @@ int main(void)
+    if (payload_length >= allocation_size) {
+        free(buffer);
+        return 2;
+    }

